package org.xvm.javajit.annotations;

import java.lang.annotation.ElementType;
import java.lang.annotation.Retention;
import java.lang.annotation.RetentionPolicy;
import java.lang.annotation.Target;

/**
 * A marker annotation to indicate that the annotated element should be generated by the JIT from
 * the natural Ecstasy code. The content of an annotated method will be replaced by the
 * corresponding natural code for that method.
 */
@Retention(RetentionPolicy.RUNTIME)
@Target(ElementType.METHOD)
public @interface JitFromNatural {
}
